void ui_category_edit(const char*key,const char*kind){Dialog d={0};d.type=4;d.kind=(char*)kind;d.key=key?_strdup(key):0;if(key){J*r=db_row(&app.db,key);d.value=dup(get(r,"data"));cJSON_Delete(r);}else{d.value=cJSON_CreateObject();char id[80];uuid(id);ss(d.value,"id",id);ss(d.value,"name","");ss(d.value,"description","");set(d.value,"archived",cJSON_CreateFalse());}show_dialog(&d,!strcmp(kind,"projects")?L"项目":!strcmp(kind,"tags")?L"标签":L"地点");free(d.key);}
void ui_calendar(HWND target,int range){Dialog d={0};d.type=5;d.target=target;d.mode=range;show_dialog(&d,L"选择日期与时间");}
void ui_file(int importing){if(!detail_save(0))return;wchar_t file[32768]=L"";OPENFILENAMEW o={0};o.lStructSize=sizeof(o);o.hwndOwner=app.window;o.lpstrFile=file;o.nMaxFile=32768;o.lpstrFilter=L"JSON 数据备份\0*.json\0\0";o.lpstrDefExt=L"json";o.Flags=OFN_EXPLORER|OFN_NOCHANGEDIR|(importing?OFN_FILEMUSTEXIST:OFN_OVERWRITEPROMPT);if(importing?GetOpenFileNameW(&o):GetSaveFileNameW(&o)){if(importing){char*t=read_file(file);J*s=t?cJSON_Parse(t):0;free(t);if(s&&!strcmp(str(s,"format"),"gxtodo-sync")){J*business=dup(get(s,"state"));cJSON_Delete(s);s=business;}if(!s){ui_notice("无法读取JSON备份");return;}wchar_t text[500];swprintf(text,500,L"导入 %d 个根任务、%d 条便签。与当前数据合并，任务冲突保留副本。",cJSON_GetArraySize(get(s,"tasks")),cJSON_GetArraySize(get(s,"notes")));if(MessageBoxW(app.window,text,L"导入预览",MB_OKCANCEL)==IDOK){undo_begin("导入数据");int ok=db_import(&app.db,s);undo_finish();ui_changed(ok?"导入完成":app.db.error);}cJSON_Delete(s);}else{J*s=db_export(&app.db);char*t=json(s);if(!write_file(file,t))ui_notice("导出失败");else ui_notice("备份已导出");free(t);cJSON_Delete(s);}}}
